import re

import pytest


def title_of(html: str) -> str:
    """Return the text between <title> and </title> in an HTML string, or an empty string."""
    match = re.search(r"<title(?:\s+[^>]*)?>(.*?)</title>", html, re.IGNORECASE | re.DOTALL)
    if match is None:
        return ""
    return match.group(1)


def test_title_of_basic() -> None:
    html = "<html><head><title>My Web Page</title></head><body></body></html>"
    assert title_of(html) == "My Web Page"


def test_title_of_missing() -> None:
    html = "<html><head></head><body><h1>No Title</h1></body></html>"
    assert title_of(html) == ""


def test_title_of_empty() -> None:
    assert title_of("") == ""
    assert title_of("<title></title>") == ""


def test_title_of_case_insensitive() -> None:
    html = "<HTML><HEAD><TITLE>Uppercase Title</TITLE></HEAD></HTML>"
    assert title_of(html) == "Uppercase Title"


def test_title_of_mixed_case() -> None:
    html = "<Title>Mixed Case</tItLe>"
    assert title_of(html) == "Mixed Case"


def test_title_of_with_attributes() -> None:
    html = '<head><title lang="en" dir="ltr">Attributed Title</title></head>'
    assert title_of(html) == "Attributed Title"


def test_title_of_multiline() -> None:
    html = "<title>\n  Line 1\n  Line 2\n</title>"
    assert title_of(html) == "\n  Line 1\n  Line 2\n"


def test_title_of_first_when_multiple() -> None:
    html = "<title>First</title><p>content</p><title>Second</title>"
    assert title_of(html) == "First"


def test_title_of_unclosed_tag() -> None:
    html = "<html><head><title>Unclosed</head></html>"
    assert title_of(html) == ""

